CREATE TABLE source_change(version INTEGER PRIMARY KEY REFERENCES version, quote TEXT NOT NULL, reason TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE audit_context(audit INTEGER PRIMARY KEY REFERENCES audit, fingerprint TEXT NOT NULL) STRICT;
CREATE TABLE finding_override(id INTEGER PRIMARY KEY, finding INTEGER NOT NULL UNIQUE REFERENCES finding, revision INTEGER NOT NULL REFERENCES revision, audit INTEGER NOT NULL REFERENCES audit, context TEXT NOT NULL, reason TEXT NOT NULL CHECK(length(trim(reason))>=3), created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE publication_selection(id INTEGER PRIMARY KEY, asset TEXT NOT NULL REFERENCES asset, day TEXT NOT NULL CHECK(date(day,'+0 days') IS day AND length(day)=10), created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE operation(key TEXT PRIMARY KEY, payload TEXT NOT NULL, result INTEGER NOT NULL) STRICT;
CREATE TABLE change_preview(id TEXT PRIMARY KEY, fact TEXT NOT NULL REFERENCES fact, expected INTEGER NOT NULL REFERENCES version, wording TEXT NOT NULL, start TEXT NOT NULL, quote TEXT NOT NULL, reason TEXT NOT NULL, snapshot TEXT NOT NULL, impact TEXT NOT NULL CHECK(json_valid(impact)), created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP) STRICT;
CREATE TABLE history(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, entity INTEGER NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, imported INTEGER NOT NULL DEFAULT 0) STRICT;
INSERT INTO history(kind,entity,detail,imported) SELECT 'source',id,'Imported fact version V'||id||': '||wording,1 FROM version;
INSERT INTO history(kind,entity,detail,imported) SELECT 'revision',id,'Imported revision R'||id||' for '||asset,1 FROM revision;
INSERT INTO history(kind,entity,detail,imported) SELECT 'audit',id,'Imported audit #'||id||' for R'||revision||' on '||publication,1 FROM audit;
INSERT INTO history(kind,entity,detail,created,imported) SELECT 'approval',id,'Imported approval #'||id||' for audit #'||audit,created,1 FROM decision;
CREATE TRIGGER log_source AFTER INSERT ON source_change BEGIN INSERT INTO history(kind,entity,detail) VALUES('source',new.version,'Source V'||new.version||': '||new.quote||' — '||new.reason); END;
CREATE TRIGGER log_revision AFTER INSERT ON revision BEGIN INSERT INTO history(kind,entity,detail) VALUES('revision',new.id,'Revision R'||new.id||' for '||new.asset||': '||new.body); END;
CREATE TRIGGER log_audit AFTER INSERT ON audit BEGIN INSERT INTO history(kind,entity,detail) VALUES('audit',new.id,'Audit #'||new.id||' for R'||new.revision||' on '||new.publication||' ('||new.mode||')'); END;
CREATE TRIGGER log_override AFTER INSERT ON finding_override BEGIN INSERT INTO history(kind,entity,detail) VALUES('override',new.id,'Override #'||new.id||' for finding #'||new.finding||', R'||new.revision||': '||new.reason); END;
CREATE TRIGGER log_approval AFTER INSERT ON decision BEGIN INSERT INTO history(kind,entity,detail) VALUES('approval',new.id,'Approval #'||new.id||' for audit #'||new.audit); END;
CREATE TRIGGER log_selection AFTER INSERT ON publication_selection BEGIN INSERT INTO history(kind,entity,detail) VALUES('publication',new.id,new.asset||': selected publication '||new.day); END;
CREATE TRIGGER immutable_source_change_UPDATE BEFORE UPDATE ON source_change BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_source_change_DELETE BEFORE DELETE ON source_change BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_audit_context_UPDATE BEFORE UPDATE ON audit_context BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_audit_context_DELETE BEFORE DELETE ON audit_context BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_finding_override_UPDATE BEFORE UPDATE ON finding_override BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_finding_override_DELETE BEFORE DELETE ON finding_override BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_publication_selection_UPDATE BEFORE UPDATE ON publication_selection BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_publication_selection_DELETE BEFORE DELETE ON publication_selection BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_operation_UPDATE BEFORE UPDATE ON operation BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_operation_DELETE BEFORE DELETE ON operation BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_change_preview_UPDATE BEFORE UPDATE ON change_preview BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_change_preview_DELETE BEFORE DELETE ON change_preview BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_history_UPDATE BEFORE UPDATE ON history BEGIN SELECT raise(ABORT,'Immutable history'); END;
CREATE TRIGGER immutable_history_DELETE BEFORE DELETE ON history BEGIN SELECT raise(ABORT,'Immutable history'); END;
